WITH matched_keys AS (SELECT plan, id FROM subscriptions INTERSECT SELECT plan, id FROM subscriptions WHERE end_date <= '2024-12-01'), verified AS (SELECT s.* FROM subscriptions s INNER JOIN matched_keys k ON s.plan = k.plan AND s.id = k.id), filtered AS (SELECT id, end_date, monthly_fee, status, CAST(monthly_fee AS INT) AS monthly_fee_int, DATE_TRUNC('week', end_date) AS end_date_period FROM verified WHERE end_date >= TO_DATE('2023-09-24') AND customer_id IS NOT NULL), scored AS (SELECT *, RANK() OVER (PARTITION BY status ORDER BY monthly_fee DESC NULLS LAST) AS monthly_fee_rank, ROUND(monthly_fee / SUM(monthly_fee) OVER (PARTITION BY status), 4) AS monthly_fee_share, MAX(monthly_fee_int) OVER (PARTITION BY status ORDER BY CAST(end_date_period AS BIGINT) RANGE BETWEEN 7776000 PRECEDING AND CURRENT ROW) AS monthly_fee_int_max_90d FROM filtered), valid AS (SELECT id, end_date, monthly_fee_int, end_date_period, monthly_fee_share, monthly_fee_int_max_90d, SUBSTRING(status, 1, 4) AS status_prefix FROM scored WHERE status = 'CANCELLED'), with_windows AS (SELECT *, PERCENT_RANK() OVER (ORDER BY monthly_fee_int DESC NULLS FIRST) AS monthly_fee_int_percent_rank, AVG(monthly_fee_int_max_90d) OVER (ORDER BY CAST(end_date_period AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS monthly_fee_int_max_90d_avg_30d, DENSE_RANK() OVER (ORDER BY monthly_fee_int_max_90d NULLS FIRST) AS monthly_fee_int_max_90d_dense_rank, AVG(monthly_fee_share) OVER (ORDER BY CAST(end_date_period AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS monthly_fee_share_avg_30d, DENSE_RANK() OVER (ORDER BY monthly_fee_int_max_90d DESC) AS monthly_fee_int_max_90d_dense_rank_2 FROM valid), valid_subscriptions AS (SELECT *, monthly_fee_int_percent_rank * monthly_fee_int AS monthly_fee_int_percent_rank_times_monthly_fee_int FROM with_windows WHERE end_date >= TO_DATE('2023-09-07') AND monthly_fee_int_max_90d >= 44), enriched AS (SELECT *, CUME_DIST() OVER (ORDER BY monthly_fee_int_percent_rank_times_monthly_fee_int) AS monthly_fee_int_percent_rank_times_monthly_fee_int_cume_dist, CUME_DIST() OVER (ORDER BY monthly_fee_int_max_90d_dense_rank_2 DESC) AS monthly_fee_int_max_90d_dense_rank_2_cume_dist FROM valid_subscriptions) SELECT DATE_TRUNC('QUARTER', end_date) AS quarter_start, CASE WHEN monthly_fee_int_max_90d >= 90 THEN 'HIGH' ELSE 'LOW' END AS monthly_fee_int_max_90d_tier, COUNT(DISTINCT id) AS distinct_ids, COUNT(DISTINCT id) AS distinct_ids_2, APPROX_PERCENTILE(monthly_fee_int_max_90d_dense_rank_2_cume_dist, ARRAY(0.25, 0.5, 0.75)) AS monthly_fee_int_max_90d_dense_rank_2_cume_dist_quartiles, (UNIX_TIMESTAMP(MAX(end_date_period)) - UNIX_TIMESTAMP(MIN(end_date_period))) / 60 AS span_minutes, PERCENTILE_APPROX(monthly_fee_int_max_90d_dense_rank_2, 0.9) AS monthly_fee_int_max_90d_dense_rank_2_p90, ROUND(AVG(monthly_fee_int_max_90d), 2) AS avg_monthly_fee_int_max_90d FROM enriched GROUP BY DATE_TRUNC('QUARTER', end_date), CASE WHEN monthly_fee_int_max_90d >= 90 THEN 'HIGH' ELSE 'LOW' END
